/// Calculate how much market coin should be minted
public(package) fun mint_ctokens<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,
    coin: Coin<CoinType>,
): Balance<CToken<MarketType, CoinType>> {
    let collateral_amount = coin.value();
    assert!(collateral_amount > 0, error::reserve_zero_coin_not_allowed());

    // TODO: ensure small truncated number will not impact accuracy
    let mint_amount = float::int_div(collateral_amount, self.exchange_rate());

    self.deposit_underlying(coin);
    self.increase_ctoken_supply(mint_amount)
}

public(package) fun liquidate_ctokens<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,
    ctokens: Coin<CToken<MarketType, CoinType>>,
    liq_revenue_factor: Decimal,
): Balance<CoinType> {
    assert!(ctokens.value() > 0, error::reserve_zero_coin_not_allowed());

    let redeem_collateral_amount = self.exchange_rate<MarketType>().int_mul(ctokens.value());

    let protocol_seize_amount = liq_revenue_factor.int_mul(redeem_collateral_amount);
    let liquidator_seize_amount = redeem_collateral_amount - protocol_seize_amount;

    self.cash_reserve = self.cash_reserve.add(math::float::from(protocol_seize_amount));

    self.decrease_ctoken_supply(ctokens.into_balance());
    self.withdraw_underlying(liquidator_seize_amount)
}

public(package) fun burn_ctokens<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,
    ctokens: Coin<CToken<MarketType, CoinType>>,
): Balance<CoinType> {
    assert!(ctokens.value() > 0, error::reserve_zero_coin_not_allowed());

    let redeem_collateral_amount = self.exchange_rate<MarketType>().int_mul(ctokens.value());

    self.decrease_ctoken_supply(ctokens.into_balance());
    self.withdraw_underlying(redeem_collateral_amount)
}

public(package) fun borrow_amount<MarketType, CoinType>(self: &mut Reserve<MarketType>, amount: u64): Balance<CoinType> {
    assert!(self.cash - self.cash_reserve.ceil() > amount, error::reserve_not_enough_error());

    self.debt = self.debt.add_u64(amount);
    self.withdraw_underlying(amount)
}

public(package) fun repay_amount<MarketType, CoinType>(self: &mut Reserve<MarketType>, coin: Coin<CoinType>) {
    let repay_amount = float::from(coin.value());

    if (self.debt.lt(repay_amount)) {
        let total_debt = self.debt.ceil();

        // repay amount is more than debt, considered as donation to reserve
        self.cash_reserve = self.cash_reserve.add_u64( coin.value() - total_debt);
        self.debt = math::float::zero();
    } else {
        self.debt = self.debt.sub(repay_amount);
    };

    self.deposit_underlying(coin);
}

public(package) fun amount<MarketType, CoinType>(self: &ReserveFlashLoan<MarketType, CoinType>): u64 {
    self.amount
}

/// Returns a hot potato ReserveFlashLoan along with the coin. Technically there is no need to but adding this extra
/// type for reserve module to know all lend flash loans are properly paid. Fees are extra.
public(package) fun borrow_flash_loan<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,
    amount: u64,
): (Balance<CoinType>, ReserveFlashLoan<MarketType, CoinType>) {
    // allow flash loan to borrow reserves
    assert!(amount < self.cash, error::reserve_flash_loan_more_than_cash());
    (self.flash_loan_withdraw(amount), ReserveFlashLoan { amount })
}

public(package) fun repay_flash_loan<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,

    loan: ReserveFlashLoan<MarketType, CoinType>,
    coin: Coin<CoinType>,

    fee: Coin<CoinType>,
) {
    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});

    let ReserveFlashLoan { amount } = loan;
    assert!(coin.value() == amount, error::reserve_flash_loan_not_paid_enough());
    reserve_token_balance.underlying_balance.join(coin.into_balance());

    // fee is extra cash for the cash reserve
    if (fee.value() == 0) {
        fee.destroy_zero();
        return
    };
    self.increase_reserve_only<MarketType, CoinType>(fee);
}

/// Take cash_reserve of the protocol from the reserve
public(package) fun take_revenue<MarketType, CoinType>(self: &mut Reserve<MarketType>, amount: u64): Balance<CoinType> {
    let amount_decimal = float::from(amount);
    assert!(self.cash_reserve.ge(amount_decimal), error::take_too_much_revenue());

    self.cash_reserve = self.cash_reserve.sub(amount_decimal);
    self.withdraw_underlying(amount)
}

fun increase_ctoken_supply<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,
    amount: u64,
): Balance<CToken<MarketType, CoinType>> {
    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});

    self.total_supply = self.total_supply + amount;
    reserve_token_balance.ctoken_supply.increase_supply(amount)
}

fun decrease_ctoken_supply<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,
    balance: Balance<CToken<MarketType, CoinType>>,
){
    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});

    self.total_supply = self.total_supply - balance.value();
    reserve_token_balance.ctoken_supply.decrease_supply(balance);
}

fun increase_reserve_only<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,
    coin: Coin<CoinType>,
) {
    let reserve_token_balance: &mut ReserveBalance<MarketType, CoinType> = dynamic_field::borrow_mut(&mut self.id, ReserveBalanceKey{});

    self.cash_reserve = self.cash_reserve.add(float::from(coin.value()));
    self.cash = self.cash + coin.value();
    reserve_token_balance.underlying_balance.join(coin.into_balance());
}

fun deposit_underlying<MarketType, CoinType>(
    self: &mut Reserve<MarketType>,
    coin: Coin<CoinType>,
) {

/// @title Module for flash loan from base asset pools
module protocol::flash_loan;

use std::type_name::{Self, TypeName};
use std::string::String;

use sui::coin::Coin;
use sui::clock::Clock;

use sui::event::emit;

use x_oracle::x_oracle::XOracle;
use x_oracle::user_oracle::get_price;

use protocol::app::{ProtocolApp, PackageCallerCap};
use protocol::coin_decimals_registry::CoinDecimalsRegistry;
use protocol::market::{Market, FlashLoan};
use protocol::value::coin_value;

public struct BorrowFlashLoanEvent has copy, drop {
    market: TypeName,
    borrower: address,
    asset: TypeName,
    amount: u64,
    fee: u64,
}

public struct RepayFlashLoanEvent has copy, drop {
    market: TypeName,
    borrower: address,
    asset: TypeName,
    amount: u64,
    fee: u64,
}

public fun borrow_flash_loan<MarketType, CoinType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,

    market: &mut Market<MarketType>,

    emode_group: u8,
    amount: u64,

    ctx: &mut TxContext,
): (Coin<CoinType>, FlashLoan<MarketType, CoinType>) {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    app.ensure_has_permission(object::id(cap), protocol::whitelist_admin::flash_loan());

    borrow_flash_loan_inner<MarketType, CoinType>(market, amount, emode_group, ctx)
}

/// @notice Repay flash loan to market
/// @dev This is the only method to repay flash loan, consume the flash loan hot potato object
/// @param version The version control object, contract version must match with this
/// @param market The market object, it contains base assets, and related protocol configs
/// @param coin The coin object to repay
/// @param loan The flash loan hot potato object, which contains the borrowed amount and fee
/// @ctx The SUI transaction context object
/// @custom:T The type of asset to repay
public fun repay_flash_loan<MarketType, CoinType>(
    app: &mut ProtocolApp,
    market: &mut Market<MarketType>,

    coin: Coin<CoinType>,
    loan: FlashLoan<MarketType, CoinType>,

    ctx: &mut TxContext,
) {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    // Emit the repay flash loan event
    emit(RepayFlashLoanEvent {
        market: type_name::with_defining_ids<MarketType>(),
        borrower: ctx.sender(),
        asset: type_name::with_defining_ids<CoinType>(),
        // amount is total repay coin amount
        amount: coin.value(),
        fee: loan.fee(),
    });

    let referral = app.referral_mut();
    // Put the asset back to the market and consume the flash loan hot potato object
    market.repay_flash_loan(coin, loan, referral, std::option::none(), ctx);
}

public fun repay_flash_loan_increase_referral_qualification<MarketType, CoinType>(
    app: &mut ProtocolApp,
    market: &mut Market<MarketType>,

    coin: Coin<CoinType>,
    loan: FlashLoan<MarketType, CoinType>,

    maybe_referral_code: Option<String>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,

    ctx: &mut TxContext,
) {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    // Emit the repay flash loan event
    emit(RepayFlashLoanEvent {
        market: type_name::with_defining_ids<MarketType>(),
        borrower: ctx.sender(),
        asset: type_name::with_defining_ids<CoinType>(),
        // amount is total repay coin amount
        amount: coin.value(),
        fee: loan.fee(),
    });

    let referral = app.referral_mut();
    track_referral(referral, ctx.sender(), loan.loan_amount(), type_name::with_defining_ids<CoinType>(), coin_decimals_registry, x_oracle, clock);
    let maybe_referral_code = referral.try_map_referral_code(ctx.sender(), maybe_referral_code);

    // Put the asset back to the market and consume the flash loan hot potato object
    market.repay_flash_loan(coin, loan, referral, maybe_referral_code, ctx);
}

fun borrow_flash_loan_inner<MarketType, CoinType>(
    market: &mut Market<MarketType>,
    amount: u64,
    emode_group: u8,
    ctx: &mut TxContext,
): (Coin<CoinType>, FlashLoan<MarketType, CoinType>) {
    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());

    let (coin, flash_loan) = market.borrow_flash_loan(emode_group, amount, ctx);

    // Emit the borrow flash loan event
    emit(BorrowFlashLoanEvent {
        market: type_name::with_defining_ids<MarketType>(),
        borrower: ctx.sender(),
        asset: type_name::with_defining_ids<CoinType>(),
        fee: flash_loan.fee(),
        amount,
    });

    // Return the borrowed coin object and the flash loan hot potato object
    (coin, flash_loan)
}

fun track_referral(
    referral: &mut protocol::referral::Referral,

    who: address,

    token_amount: u64,
    token_type: TypeName,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
) {
    if (referral.is_qualified_to_create_referral_code(who)) return;

    let decimals = coin_decimals_registry.decimals(token_type);
    // always use usd price
    let usd_price = get_price(x_oracle, token_type, x_oracle::x_oracle::usd(), clock);
    let collateral_value_usd = coin_value(usd_price, math::float::from(token_amount), decimals);

    referral.increase_usd_qualification(who, collateral_value_usd.floor());
}

#[test_only]
public fun borrow_flash_loan_against_group<MarketType, CoinType>(
    market: &mut Market<MarketType>,
    amount: u64,
    emode_group: u8,
    ctx: &mut TxContext,
): (Coin<CoinType>, FlashLoan<MarketType, CoinType>) {
    borrow_flash_loan_inner<MarketType, CoinType>(market, amount, emode_group, ctx)
}

